L=load('life_prepare',HERE/'prepare-lifecycle.py');V=load('life_validate',ROOT/'experiments/s-integrate/measurement-lifecycle-run.py');e={'subject':'actual Lifecycle Motion64 JS','mutation':'physical pending observation forced zero','limits':{'checker':5,'runtime':5,'codegen':30},'cpu':8}
