 root=pathlib.Path(directory);dest=R.materialize(root);P.prepare(dest);L.prepare(dest);p=dest/'occupancy.bend';s=p.read_text();assert 'U32.show(pending)' in s;p.write_text(s.replace('U32.show(pending)','U32.show(0)'));entry=dest/'measurement-lifecycle.bend';e['closure']=R.closure(entry)
 try:
  assert 'ALL PROOFS CHECK' in ''.join(R.run(['taskset','-c','8','bend',entry,'--check-only']));js=root/'pending-zero.js';R.run(['taskset','-c','8','bend',entry,'-o',js],30);e['generatedJsSha256']=hashlib.sha256(js.read_bytes()).hexdigest();text=R.run(['taskset','-c','8','node',js,'0','64'])[0];public='\n'.join(l for l in text.splitlines() if not l.startswith(('lifediag:','txdiag:')))+'\n';oracle=json.loads((HERE/'lifecycle-evidence.json').read_text())['cases'][0]['backends']['JS'];assert hashlib.sha256(public.encode()).hexdigest()==oracle['publicSha256'];ref=json.loads(R.run(['taskset','-c','8','node',ROOT/'experiments/s-integrate/measurement-reference.mjs','Motion','lifecycle','64'])[0]);e['freshTSValidation']=V.validate(public,'Motion',64,ref);lines=[l for l in text.splitlines() if l.startswith('lifediag:')];assert len(lines)==514;pending=[int(l.split(':',6)[6].split(':')[3]) for l in lines];assert max(pending)==0;assert oracle['worldPendingPeak']==64 and oracle['systemPendingPeak']==2;e.update(status='DETECTED',publicTraceMatch=True,publicSha256=oracle['publicSha256'],oracleFailure='actual setup pending must equal 64 and after-system peak must equal 2; mutant reports zero',checkpoints=len(lines))
 except Exception as exc:e.update(status='UNAVAILABLE',error=str(exc))
